DROP TABLE IF EXISTS `approval_action_log`;
CREATE TABLE `approval_action_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `action_type` bigint NULL DEFAULT NULL COMMENT '操作类型ID',
  `action_icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作日志对应的图片类型',
  `action_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作日志对应的显示状态名称',
  `serial_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批流水编号',
  `business_id` bigint NULL DEFAULT NULL COMMENT '业务id',
  `module_id` bigint NULL DEFAULT NULL COMMENT '模块id',
  `status_group_id` bigint NULL DEFAULT NULL COMMENT '当前业务主状态id',
  `status_id` bigint NULL DEFAULT NULL COMMENT '当前业务状态id',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '动作内容描述',
  `real_user_id` bigint NULL DEFAULT NULL COMMENT '真实操作人(当前登录人)',
  `real_user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '真实操作人(当前登录人)名称',
  `created_by` bigint NULL DEFAULT NULL COMMENT '模拟操作用户',
  `created_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模拟操作用户名称',
  `created_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 618 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单据审批操作日志' ROW_FORMAT = DYNAMIC;

