DROP TABLE IF EXISTS `approval_business`;
CREATE TABLE `approval_business`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '单据ID',
  `subject_id` bigint NOT NULL DEFAULT 0 COMMENT '主体ID',
  `module_id` bigint NOT NULL COMMENT '模块ID',
  `approval_chain_type_id` bigint NULL DEFAULT NULL COMMENT '当前审批链分类ID',
  `business_id` bigint NULL DEFAULT NULL COMMENT '真实业务ID',
  `record_id` bigint NULL DEFAULT NULL COMMENT '业务记录ID',
  `business_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `serial_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审批流编号',
  `version_no` int NOT NULL DEFAULT 1 COMMENT '当前单据版本号',
  `serial_no` int NOT NULL DEFAULT 1 COMMENT '当前审批流版本号',
  `current_step` int NOT NULL DEFAULT 1 COMMENT '当前审批流步骤',
  `status_id` bigint NOT NULL COMMENT '当前审批流状态ID',
  `status_value` int NOT NULL DEFAULT 0 COMMENT '当前审批流状态',
  `status_title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态名称',
  `status_background` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态背景色',
  `status_font_color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态字体颜色',
  `approve_role_id` bigint NOT NULL COMMENT '当前审批角色组',
  `approver_id` bigint NULL DEFAULT NULL COMMENT '当前指定审批人ID',
  `approver_id_list` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前步骤已审批人',
  `approval_uids` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '历史审批人ID-审批角色ID列表，如 2-3,3-3',
  `created_by` bigint NULL DEFAULT NULL COMMENT '单据申请人ID',
  `created_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据申请人名称',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更改人ID',
  `updated_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更改人名称',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '\'1:删除,0:正常\'',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `module_id_index`(`module_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 112 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '通用单据列表' ROW_FORMAT = DYNAMIC;

