-- ----------------------------
-- Table structure for approval_chain
-- ----------------------------
DROP TABLE IF EXISTS `approval_chain`;
CREATE TABLE `approval_chain`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `pid` bigint NOT NULL DEFAULT 0 COMMENT '父id',
  `module_id` bigint NULL DEFAULT 0 COMMENT '所属模块ID 0表示不属于模块',
  `serial_number` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '审批流水编号',
  `serial_no` int NOT NULL DEFAULT 1 COMMENT '审批流版本号',
  `pid_module_hash` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'pid和moduleId的哈希值',
  `current_step` int NULL DEFAULT 1 COMMENT '当前步骤',
  `next_step` int NULL DEFAULT 2 COMMENT '下一步步骤',
  `up_step` int NULL DEFAULT 0 COMMENT '上一步步骤',
  `approval_chain_type_id` bigint NULL DEFAULT NULL COMMENT '审批链分类',
  `approval_rule` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审批规则',
  `reject_rule` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '驳回规则',
  `role_approval_percent` int NULL DEFAULT 0 COMMENT '0~100 approval_rule为3时设置需要审批人数的百分比',
  `approve_role_id` bigint NULL DEFAULT NULL COMMENT '审批角色组  sys_role表的id 审批角色组  approvale_rule 为1  2  3时',
  `approver_id` bigint NULL DEFAULT NULL COMMENT '审批人  sys_user表的id  approval_rule为0时',
  `approver_id_list` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '当前步骤已审批人，驳回会会清空，用于百分比判断',
  `reason` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审批原因',
  `delegate_approver_id` bigint NULL DEFAULT NULL COMMENT '移交人id  approval_rule 为0时使用',
  `skipped` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否跳过步骤  1:跳过  0:不跳过',
  `showed` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1:显示，0:隐藏',
  `child_module_ids` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '子模块集合Id, 英文逗号分隔',
  `current_status_group_id` bigint NOT NULL DEFAULT 0 COMMENT '当前主状态id',
  `current_status_child_id` bigint NOT NULL DEFAULT 0 COMMENT '当前子状态id',
  `next_status_group_id` bigint NOT NULL DEFAULT 0 COMMENT '下一主状态id',
  `next_status_child_id` bigint NOT NULL DEFAULT 0 COMMENT '下一子状态id',
  `auto_approved` tinyint NULL DEFAULT 0 COMMENT '1:自动审批，0:不能自动审批，默认为0',
  `auto_approved_time` int NULL DEFAULT NULL COMMENT '系统自动办理时间  auto_approved为1时必填',
  `deadline_time` datetime NULL DEFAULT NULL COMMENT '办理人未办理的最迟时间  auto_approved_time为0时可填',
  `button_list` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '按钮Id列表',
  `collaborated` tinyint NULL DEFAULT 0 COMMENT '是否协同办理 0:否  1:是',
  `repeated` tinyint NULL DEFAULT 0 COMMENT '是否可以重复提交 0:否  1:是',
  `msg_template_ids` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '消息模板Id集合, 英文逗号分隔',
  `default_flag` tinyint NULL DEFAULT 0 COMMENT '是否默认，1：是，0：否',
  `approval_uids` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '当前步骤已办理过的人id集合, 英文逗号分隔，不会清空',
  `approval_uid` bigint NULL DEFAULT NULL COMMENT '当前步骤已办理过的人id',
  `approved` tinyint NULL DEFAULT 0 COMMENT '是否已审批，1：是，0：否',
  `sended_msg` tinyint NULL DEFAULT 0 COMMENT '是否发送过消息，1：是，0：否',
  `created_by` bigint NULL DEFAULT NULL COMMENT '创建人（用户表id）',
  `created_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建人名称（用户表user_name）',
  `created_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更改人（用户表id）',
  `updated_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更改名称（用户表user_name）',
  `updated_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `pid`(`pid` ASC, `approved` ASC, `current_step` ASC) USING BTREE,
  INDEX `pid_module_hash`(`pid_module_hash` ASC, `approved` ASC, `current_step` ASC, `pid` ASC) USING BTREE,
  INDEX `approve_role_id`(`approve_role_id` ASC, `approval_rule` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 442 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '单据审批链记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of approval_chain
-- ----------------------------

