-- Table structure for approval_chain_button
-- ----------------------------
DROP TABLE IF EXISTS `approval_chain_button`;
CREATE TABLE `approval_chain_button`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `pid` bigint NULL DEFAULT NULL COMMENT 'approval_chain表对应的ID',
  `serial_number` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '审批流水编号',
  `serial_no` int NOT NULL DEFAULT 1 COMMENT '审批流版本号',
  `current_step` int NULL DEFAULT 1 COMMENT '当前步骤',
  `button_type_id` bigint NULL DEFAULT NULL COMMENT '操作类型 sys_config表对应的ID',
  `button_type_value` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作类型 sys_config_item表对应的Value',
  `button_id` bigint NULL DEFAULT NULL COMMENT '按钮 sys_config_button按钮表对应ID',
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '日志对应图标',
  `log_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '日志对应状态描述',
  `auto_next_task_flag` tinyint NULL DEFAULT NULL COMMENT '是否自动进入下一任务',
  `msg_template_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息模板 sys_wechat_template对应ID',
  `created_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `created_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名称',
  `created_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更改人',
  `updated_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更改名称）',
  `updated_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 879 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单据审批链记录按钮表' ROW_FORMAT = DYNAMIC;

