-- ----------------------------
-- Table structure for sys_monitor_controllog
-- ----------------------------
DROP TABLE IF EXISTS `sys_monitor_controllog`;
CREATE TABLE `sys_monitor_controllog`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID;自增主键',
  `subject_id` bigint NOT NULL COMMENT '主体ID;（多主体、多租户）',
  `subject_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主体名称',
  `approvalType` int NULL DEFAULT 1 COMMENT '审批类型：0，自动审批。1，手动审批',
  `actionName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '动作名称',
  `actionPath` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批动作图标',
  `actionType` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批类型，前端根据类型决定审批结果字体颜色',
  `actionTypeTitle` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批结果',
  `login_user_id` bigint NOT NULL COMMENT '登录用户ID',
  `login_user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录用户名',
  `login_avater` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人头像',
  `login_user_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人工号',
  `login_role_id` bigint NOT NULL COMMENT '登录用户的角色ID',
  `login_role_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人角色名称',
  `login_user_dept_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人部门ID;多个ID，用逗号分割',
  `login_user_dept_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人部门名称;多个名称，用逗号分割',
  `login_user_job_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '登录人岗位ID;多个ID，用逗号分割',
  `login_user_job_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '登录人岗位名称;多个名称，用逗号分割',
  `mock_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否mock标记;：0，否；1 是',
  `mock_user_id` bigint NULL DEFAULT 0 COMMENT '模拟用户ID',
  `mock_user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟用户名称',
  `mock_user_avater` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟用户头像',
  `mock_user_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟用户工号',
  `ip` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '日志发生的IP地址',
  `module_id` bigint NULL DEFAULT NULL COMMENT '模块ID',
  `module_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模块名称;系统设置/元件管理/',
  `menu_id` bigint NULL DEFAULT NULL COMMENT '菜单ID',
  `href_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '超链接文本',
  `menu_param` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '菜单参数;菜单配置中的参数内容',
  `data_id` bigint NULL DEFAULT NULL COMMENT '数据表记录ID',
  `orderVersion` int NULL DEFAULT NULL COMMENT '单据版本号',
  `control_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单据操作名称;元件审核/权限配置/审批链配置',
  `operator_result` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作结果/执行结果/处理结果;成功/失败',
  `font_color` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '字体颜色;获取系统中配置的颜色，默认为黑色',
  `browser` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'chrome' COMMENT '浏览器信息',
  `plat_form` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'windows' COMMENT '平台信息',
  `system_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '系统名称',
  `log_content` json NULL COMMENT '日志内容',
  `log_remark` json NULL COMMENT '日志备注',
  `log_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '日志时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1061 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统监控操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_monitor_controllog
-- ----------------------------

