  `control_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单据操作描述',
  `log_sub_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '日志子类型systemLog：系统日志；systemNavLog：导航日志',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7064 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统监控系统日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_monitor_systemlog
-- ----------------------------

-- ----------------------------
-- Table structure for table_change_log
-- ----------------------------
DROP TABLE IF EXISTS `table_change_log`;
CREATE TABLE `table_change_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `data_id` bigint NOT NULL COMMENT '用户ID',
  `subject_id` bigint NOT NULL COMMENT '用户的主题ID',
  `module_id` bigint NOT NULL DEFAULT 0 COMMENT '模块ID',
  `module_slug` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '模块标识符',
  `module_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '模块名称',
  `change_content` json NULL COMMENT '变更字段内容',
  `mock_user_id` bigint NULL DEFAULT NULL COMMENT '模拟用户ID',
  `mock_user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模拟用户名称',
  `mock_department_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模拟用户部门ID',
  `mock_department_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模拟用户部门名称',
  `mock_job_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模拟用户岗位ID',
  `mock_job_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模拟用户岗位名称',
  `real_user_id` bigint NULL DEFAULT NULL COMMENT '登录用户ID',
  `real_user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '登录用户名称',
  `real_department_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '真实用户部门ID',
  `real_department_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '真实用户部门名称',
  `real_job_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '真实用户岗位ID',
  `real_job_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '真实用户岗位名称',
  `created_by` bigint NULL DEFAULT NULL COMMENT '操作用户',
  `created_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作用户名称',
  `created_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更改人',
  `updated_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更改人名称',
  `updated_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更改时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '1删除0正常',
  PRIMARY KEY (`id`) USING BTREE,
  CONSTRAINT `user_change_log_chk_1` CHECK (`deleted` in (0,1))
) ENGINE = InnoDB AUTO_INCREMENT = 22887 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

